import glob,yaml,json
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    y=yaml.safe_load(open(f)); rows[y['id']]=y
tasks=json.load(open('/tmp/tasks2.json'))['tasks']
running={t['id'] for t in tasks if t['status']=='running'}
refs={}
for t in tasks:
    for r in (t.get('roadmap_refs') or []): refs.setdefault(r,[]).append((t['id'],t['status']))
def par(i):
    y=rows.get(i) or {}
    return (y.get('metadata') or {}).get('parent') or y.get('parent')
active=[i for i,y in rows.items() if y.get('status')=='active']
direct=set()
for a in active:
    y=rows[a]; md=y.get('metadata') or {}
    if (md.get('owner') in running) or any(t in running for t,_ in refs.get(a,[])) or any(t in running for t in (y.get('task_refs') or [])):
        direct.add(a)
# ancestors of direct
anc=set()
for a in direct:
    p=par(a)
    while p:
        if rows.get(p,{}).get('status')=='active': anc.add(p)
        p=par(p)
print('ACTIVE ROWS:',len(active))
print('DIRECTLY HELD by live lane:',len(direct)); [print('   ',x) for x in sorted(direct)]
print('ACTIVE ANCESTORS of those:',len(anc-direct)); [print('   ',x) for x in sorted(anc-direct)]
left=sorted(set(active)-direct-anc)
print('LEFTOVER (candidates):',len(left))
for l in left:
    md=rows[l].get('metadata') or {}
    print('   ',l,'| owner',md.get('owner'),'| heldby',refs.get(l))
"

